{
  "implementation": "def solve(case):
    # Validate required fields
    required = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for field in required:
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    # Validate transitions structure
    for state, trans in transitions.items():
        if 'kind' not in trans:
            raise ValueError(f"Transition for state '{state}' missing 'kind'")
        if trans['kind'] == 'action':
            if 'action' not in trans or 'next_by_observation' not in trans or 'default_next' not in trans:
                raise ValueError(f"Action state '{state}' missing required fields")
            action = trans['action']
            if action not in tool_obs:
                raise ValueError(f"Tool '{action}' referenced in state '{state}' not in tool_observations")
        elif trans['kind'] == 'final':
            if 'value' not in trans:
                raise ValueError(f"Final state '{state}' missing 'value'")
        else:
            raise ValueError(f"Unknown kind '{trans['kind']}' for state '{state}'")

    # Validate initial state exists
    if initial not in transitions:
        raise ValueError(f"Initial state '{initial}' not in transitions")

    current_state = initial
    step = 0
    trace = []
    status = None
    final_value = None

    while True:
        trans = transitions[current_state]
        if trans['kind'] == 'final':
            status = 'completed'
            final_value = trans['value']
            break
        elif trans['kind'] == 'action':
            step += 1
            if step > max_steps:
                status = 'max_steps_exceeded'
                final_value = None
                break
            action = trans['action']
            observation = tool_obs[action]
            # Record trace
            trace.append({
                'step': step,
                'action': action,
                'observation': observation,
                'state': current_state
            })
            # Determine next state
            next_by_obs = trans['next_by_observation']
            if observation in next_by_obs:
                next_state = next_by_obs[observation]
            else:
                next_state = trans['default_next']
            # Validate next state exists
            if next_state not in transitions:
                raise ValueError(f"Transition from state '{current_state}' leads to undefined state '{next_state}'")
            current_state = next_state

    return {
        'status': status,
        'final': final_value,
        'trace': trace
    }
